        { 1318, nil, 56, 60, nil, nil, nil, false, nil, {18366, 18367, 18368, 18369}, nil, "Doable in one run. Recommended route: North first (tribute run — bring the ogre-suit materials and the broken trap) → West (kill Immol'thar) → Library (kill Prince Tortheldrin) → back to North, turn in to Fengus on the way out.", {{56,2}, {58,3}, {63,4}, {72,5}}, {18336}, nil, nil, nil, { xp = 8300 } },
        { 5526, nil, 56, nil, "Rabine Saturna", "Moonglade 51,44", "Shards of the Felvine", false, {5527}, { 18535, 18536 }, "Find the warped vine in Dire Maul and collect a fragment (you must kill Ozien first), seal it with the Purification Cask, and bring it to Rabine Saturna at Nighthaven in Moonglade.", "奥兹恩在厄运之槌东区。净化之匣(希利苏斯 62,54)。前置同样来自拉比恩·萨图纳。", {{56,2}, {58,3}, {63,4}, {72,5}}, {18540, 18539}, nil, 11801, "Rabine Saturna", { xp = 8300, rep = { { 609, 150, "[UNUSED] Brother Milius" } } } },
