        { 1193, nil, 56, nil, "A Broken Trap", "Dire Maul: North", nil, false, nil, nil, "Repair the trap.", "Repeatable. Repairing it requires a [Thorium Widget] and a vial of [Frost Oil].", {{56,2}, {58,3}, {63,4}, {72,5}}, {15994, 3829}, nil, nil, nil, nil },
        { 1318, nil, 56, 60, nil, nil, nil, false, nil, {18366, 18367, 18368, 18369}, nil, "Doable in one run. Recommended route: North first (tribute run — bring the ogre-suit materials and the broken trap) → West (kill Immol'thar) → Library (kill Prince Tortheldrin) → back to North, turn in to Fengus on the way out.", {{56,2}, {58,3}, {63,4}, {72,5}}, {18336}, nil, nil, nil, { xp = 8300 } },
        { 5518, nil, 56, 60, "Knot Thimblejack", "Dire Maul: North,", nil, true, nil, {18258}, "Bring 4 Runecloth, 8 Rugged Leather, 2 Rune Thread and an Ogre Tannin to Nott Shimjak, who is chained up in the Gordok ogre area of Dire Maul.", "Repeatable. The Ogre Tannin is obtained near the upper part of the instance.", {{56,2}, {58,3}, {63,4}, {72,5}}, {14048, 8170, 14341, 18240}, nil, 14338, "Knot Thimblejack", { xp = 6600, rep = { {169, 100, "Steamwheedle Port"} } } },
