        { 7703, nil, 56, nil, "Captain Kromcrush", "Dire Maul: North,", nil, false, nil, { 18366, 18367, 18368, 18369 }, "Find the Gauntlet of Gordok Might and bring it to Captain Kromcrush in Dire Maul.", "王子在厄运之槌西；力量护手在他附近的箱子里。推荐顺序：先北拿贡品、带着《当国王真好》状态 → 西杀王子开箱 → 回北交任务。", {{56,2}, {58,3}, {63,4}, {72,5}}, {18336}, nil, 14325, "Captain Kromcrush", { xp = 22200 } },
        { 7877, "H", 56, 60, "Shen'dralar Ancient", "Dire Maul: West (upper level)", "The Treasure of the Shen'dralar", true, {7461}, {18420, 18421, 18424}, "Return to the Library to find the Shen'dralar treasure and claim your reward!", "The treasure is under the ladder in the Library.", {{56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 14358, "Shen'dralar Ancient", { xp = 660, money = 27000 } },
        { 5525, nil, 57, 60, "Knot Thimblejack", "Dire Maul: North,", nil, true, nil, nil, "Find the ogre shackle key for Nott.", "Repeatable; every ogre in the instance can drop it.", {{56,2}, {58,3}, {63,4}, {72,5}}, {18250}, nil, 14338, "Knot Thimblejack", { xp = 6600, rep = { {169, 150, "Steamwheedle Port"} } } },
