    ["upper_blackrock_spire"] = {
        { 6502, "A", 50, 60, "Haleh", "Winterspring 54.4,51.2", "Drakefire Amulet", false, {6501}, {16309}, nil, nil, {{50,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {16663}, nil, 10929, "Haleh", { xp = 8300 }},
        { 4974, "H", 55, 60, "Thrall", "Orgrimmar 31,38", "For The Horde!", false, {4941}, {13966, 13968, 13965}, "Kill Warchief Rend Blackhand in Blackrock Spire and return to Orgrimmar with his head.", "Rend Blackhand is inside the instance.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {12630}, nil, 4949, "Thrall", { xp = 9950, money = 27000, rep = { {76, 200, "Orgrimmar"}, {530, 200, "Darkspear Trolls"}, {68, 200, "Undercity"}, {81, 200, "Thunder Bluff"} } } },
        { 5047, nil, 55, 60, "Finkle Einhorn", "Upper Blackrock Spire", nil, true, nil, nil, "Talk with Marevus Darkhammer in Everlook.", "剥完比斯巨兽的皮后芬克·恩霍尔才会出现。玛雷弗斯·暗锤(冬泉谷-永望镇 61,38)。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12710}, nil, 10776, "Pip Quickwit", { xp = 6600 } },
        { 5102, "A", 55, 60, "Marshal Maxwell", "Burning Steppes - Morgan's Vigil 82,68", "General Drakkisath's Demise", false, {5089}, {13966, 13968, 13965}, "Kill General Drakkisath in Blackrock Spire and report back to Marshal Maxwell.", "General Drakkisath is inside the instance.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 9560, "Marshal Maxwell", { xp = 9950, money = 27000, rep = { {469, 200, "[UNUSED] Brother Milius"} } } },
        { 5127, nil, 55, 60, "Lorax", "Winterspring 64,74", "The Demon Forge", false, {5126}, {12696, 9224, 12849}, "Find Gularuk in Blackrock Spire; after killing him, thrust the Bloodstained Spear into the corpse to drain its soul and forge the Soulpiercer; then find an unforged Runed Breastplate and bring both to Lorax in Winterspring.", "Blacksmithing quest. Goraluk is inside the dungeon. Requires Blacksmithing 270 to pick up.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {12847, 12806, 12848}, nil, 10918, "Lorax", { xp = 8300 } },
        { 6569, "H", 55, nil, "Myranda the Hag", "Western Plaguelands 50,77", "Oculus Illusions", false, {6568}, nil, "Collect 20 Black Dragon Whelp eyes in Blackrock Spire, then report back to Myranda the Hag.", "All black dragonkin drop the eyes.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {16786}, nil, 11872, "Myranda the Hag", { xp = 6600 } },
        { 6602, "H", 55, 60, "Rokaro", "Desolace - Shadowprey Village 25,71", "Blood of the Black Dragon Champion", false, {6601}, {16309}, "Kill General Drakkisath in Blackrock Spire and bring his blood to Rokaro.", "The final step of the Onyxia prerequisite chain. General Drakkisath is inside the instance.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {16663}, nil, 10182, "Rokaro", { xp = 9950 } },
        { 6821, nil, 55, nil, "Duke Hydraxis", "Azshara 79,73", "Eye of the Emberseer", false, {6804}, nil, "Bring the Eye of Ebohir to Duke Hydraxis in Azshara.", "Ebohir is inside the instance. This quest chain can no longer be started after patch 3.0.8; characters who already have it are unaffected and can still complete it.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {17322}, nil, 13278, "Duke Hydraxis", { xp = 8300 } },
        { 7761, nil, 55, nil, nil, "Blackhand's Command drops from the Scarshield Quartermaster (on the dungeon entrance map).", nil, true, nil, nil, "What a dim-witted orc — find the brand and obtain Drakkisath's Badge before you can use the Orb of Command.", "The Blackwing Lair attunement quest. The Scarshield Quartermaster is near the right side of the Blackrock Spire entrance; the orb is behind General Drakkisath.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {18987}, nil, nil, nil, { xp = 6600 } },
        { 4734, nil, 57, 60, "Tinkee Steamboil", "Burning Steppes - Flame Crest 65,24", "Tinkee Steamboil", false, {4810}, {12144}, "Use the Egg Freezer Mark I on a dragon egg in the hatchery.", "The eggs are in the Father Flame's room. After freezing an egg do NOT click it — use the device from your backpack; after killing General Drakkisath you can jump straight down to the rookery and finish it separately.", {{57,2}, {58,3}, {63,4}, {72,5}}, {12286}, nil, 10267, "Tinkee Steamboil", { xp = 8300, money = 18000, rep = { {169, 150, "Steamwheedle Port"} } } },
        { 4735, nil, 57, 60, "Tinkee Steamboil", "Burning Steppes - Flame Crest 65,24", "Egg Collection", false, {4734}, nil, "Bring the Electric Collection Module and 8 dragon eggs to Tinkee Steamboil at Flame Crest in the Burning Steppes.", "The eggs are all in the Father Flame's room. After freezing an egg, get close and use the device from your backpack (don't click the egg); if the raid won't wait, jump down to the rookery after the General to finish it solo.", {{57,2}, {58,3}, {63,4}, {72,5}}, {12241, 12287}, nil, 10267, "Tinkee Steamboil", { xp = 9950, money = 27000, rep = { {169, 200, "Steamwheedle Port"} } } },
        { 4764, "A", 57, 60, "Mayara Brightwing", "Burning Steppes - Morgan's Vigil 84,69", "Mayara Brightwing", false, {4766}, nil, "Bring Doomrigger's Clasp to Mayara Brightwing in the Burning Steppes.", "前置可从雷明顿·瑞治维尔伯爵接(暴风城-暴风要塞 77,47)。扣环在烈焰之父房间的箱子里。箱子约 20 秒刷新一次，多人可轮流开。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12352}, nil, 9565, "Mayara Brightwing", { xp = 1650, rep = { {72, 25, "Stormwind City"} } } },
        { 4765, "A", 57, 60, "Mayara Brightwing", "Burning Steppes 84.8,69.0", nil, false, {4764}, {15861, 15860}, nil, nil, {{57,2}, {58,3}, {63,4}, {72,5}}, {12437}, nil, 9565, "Mayara Brightwing", { xp = 6600, money = 27000, rep = { {72, 100, "Stormwind City"} } }},
        { 4768, "H", 57, 60, "Vivian Lagrave", "Badlands - Kargath 2,47", "The Darkstone Tablet", false, {4769}, {15861, 15860}, "Bring the Darkstone Tablet to Shadowmage Vivian Lagrave in Kargath.", "前置可从药剂师金格接(幽暗城-炼金房 50,68)。石板在上层黑石塔的龙蛋房（孵化场）。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12358}, nil, 9078, "Shadowmage Vivian Lagrave", { xp = 8300, money = 27000, rep = { {68, 150, "Undercity"} } } },
        { 5160, nil, 57, 60, "Awbee", "Upper Blackrock Spire", nil, true, nil, nil, "Find Haleh in Winterspring and bring her Awbee's scale.", "奥比在竞技场旁的房间，蹲在一处凸台上。哈尔琳(冬泉谷 54,51)；从洞穴最里面的传送符文站上去就能到她身边。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12923}, nil, 10740, "Awbee", { xp = 6600 } },
        { 8989, nil, 58, 60, "Bodley", "Blackrock Mountain dungeon-entrance map [D]", "More Vital Materials", false, {8986}, nil, "Use the summoning brazier in the Beast's room to call out Duke Vatalak; after killing him, use the Vatalak Trinket on the corpse, then return the trinket to the Spirit of Duke Vatalak.", "You need the Extraplanar Ghost Revealer to see Bodley (from 'Finding Anthion'). Mor Grayhoof is summoned inside the dungeon.", {{58,3}, {63,4}, {72,5}}, {22048, 22049}, nil, 16033, "Bodley", { xp = 8300 } },
        { 8994, nil, 58, nil, "Bodley", "Blackrock Mountain dungeon-entrance map [D]", "The Right Half of the Vatalak Trinket", false, {8989}, nil, "Collect 40 Blackrock bracers from the orcs of Blackrock Spire and hand them, together with 1 Super Energy Potion, to Bodley at Blackrock Mountain.", "You need the Extraplanar Ghost Revealer to see Bodley (from 'Finding Anthion'). The bracers drop from Blackrock Spire orcs; the Super Energy Potion is an alchemy product.", {{58,3}, {63,4}, {72,5}}, {22138, 13512, 22048}, nil, 16033, "Bodley", { xp = 6600 } },
        { 8995, nil, 58, 60, "Bodley", "Blackrock Mountain dungeon-entrance map [D]", "The Final Preparation", false, {8994}, nil, "Use the summoning brazier in the Beast's room to call out Duke Vatalak; after killing him, use the Vatalak Trinket on the corpse, then return the trinket to the Spirit of Duke Vatalak.", "You need the Extraplanar Ghost Revealer to see Bodley (from 'Finding Anthion'). Duke Vatalak is summoned inside the dungeon; claim the reward from Bodley.", {{58,3}, {63,4}, {72,5}}, {22048, 22056}, nil, 16033, "Bodley", { xp = 9950 } },
    },
    ["onyxias_lair"] = {
        { 4182, "A", 48, 54, "Helendis Riverhorn", "Burning Steppes - Morgan's Vigil 85.6,69", nil, false, nil, nil, "Slay the black dragonkin in Burning Steepes and report back to Helendis Riverhorn.", "Alliance attunement step one. Black Broodlings and whelps are non-elite; Black Dragonspawn, Wyrmkin and Drakes are level 50-54 elites — bring a group. They are all strung along the eastern edge of the zone.", {{48,1}, {50,2}, {52,3}, {57,4}, {65,5}}, nil, nil, 9562, "Helendis Riverhorn", { xp = 5450, rep = { { 69, 100, "Darnassus" } } } },
        { 4183, "A", 48, 54, "Helendis Riverhorn", "Burning Steppes - Morgan's Vigil 85.6,69", nil, false, {4182}, nil, "Deliver Helendis Riverhorn's letter to Magistrate Solomon in Lakeshire, Redridge Mountains.", "同名任务共五段，从湖畔镇一路辗转推进到暴风城。本段终点：湖畔镇市政厅(赤脊山 30,44)。", {{48,1}, {50,2}, {52,3}, {57,4}, {65,5}}, nil, nil, 344, "Magistrate Solomon", { xp = 4100, rep = { { 69, 75, "Darnassus" } } } },
        { 4241, "A", 50, 58, "Marshal Maxwell", "Burning Steppes - Morgan's Vigil 84.6,68.8", nil, false, {4183}, nil, "Visit Marshal Windsor in the Blackrock Depths jail and deliver Marshal Maxwell's letter to him.", "Windsor is in the cell at the end of the corridor on the right side of the BRD jail block. Do not mix the two up: Marshal Maxwell is at Morgan's Vigil in Burning Steepes, while Marshal Windsor is in the BRD jail.", {{50,1}, {54,2}, {56,3}, {61,4}, {69,5}}, nil, nil, 9023, "Marshal Windsor", { xp = 11450, rep = { { 72, 100, "Stormwind City" } } } },
        { 6402, "A", 50, 60, "Marshal Maxwell", "Burning Steppes - Morgan's Vigil 84.6,68.8", nil, false, {4322}, nil, "Find Squire Rowe at the gates of Stormwind City to summon Reginald Windsor, then escort him from the gates to Stormwind Keep.", "The escort takes about 10 minutes. If another party is already escorting him, Windsor says he is indisposed at the moment — wait a few minutes and he will show up.", {{50,1}, {54,2}, {56,3}, {61,4}, {69,5}}, nil, nil, 12580, "Reginald Windsor", { xp = 660 } },
        { 6403, "A", 50, 60, "Reginald Windsor", "Stormwind City - main gates 70.4,85.6", nil, false, {6402}, nil, "March with Reginald Windsor to Stormwind Keep, defeat the elite dragonkin guards summoned when Lady Katrana Prestor reveals her true form, then report to Highlord Bolvar Fordragon.", "The Great Masquerade: Lady Prestor reveals herself as Onyxia and summons elite dragonkin guards; the nearby guard NPCs help tank them. Turn in the quest once everything is defeated.", {{50,1}, {54,2}, {56,3}, {61,4}, {69,5}}, nil, nil, 1748, "Highlord Bolvar Fordragon", { xp = 9950, rep = { { 72, 200, "Stormwind City" } } } },
        { 6501, "A", 50, 60, "Highlord Bolvar Fordragon", "Stormwind City", nil, false, {6403}, nil, "Take the Fragment of the Dragon's Eye deep into the cave of Mazthoril in southern Winterspring to find Haleh, a dragon disguised as a humanoid.", "Haleh stands at the teleport runes at the end of the cave — step on the runes to reach her. The cave is stuffed with elite dragons: clear through with a group, stealth down, or sprint straight to her.", {{50,1}, {54,2}, {56,3}, {61,4}, {69,5}}, nil, nil, 10929, "Haleh", { xp = 6600 } },
        { 4941, "H", 55, 60, "Warlord Goretooth", "Badlands - Kargath 5.8,47.6", nil, false, {4903}, nil, "Speak with Eitrigg in the Valley of Wisdom in Orgrimmar, then bring his words to Thrall.", "伊崔格在智慧谷(34.4,38.4)，谈完直接回萨尔(奥格瑞玛 31,38)交任务。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 4949, "Thrall", { xp = 6600, rep = { { 76, 100, "Orgrimmar" } } } },
        { 6566, "H", 55, 60, "Thrall", "Orgrimmar 31,38", nil, false, {4974}, nil, "Listen to Thrall's tale, then turn the quest in to him.", "A pure dialogue quest — just stand there and listen.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 4949, "Thrall", { xp = 660 } },
        { 6567, "H", 55, 60, "Thrall", "Orgrimmar 31,38", nil, false, {6566}, nil, "Find Rexxar, champion of the Horde, in Desolace.", "Rexxar patrols back and forth along the road between Stonetalon Mountains and Feralas, cutting through the Kodo Graveyard midway. If you cannot find him, ask in Desolace general chat, or run north from Feralas — that is the easiest way to catch him.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10182, "Rokaro", { xp = 3300 } },
        { 6568, "H", 55, 60, "Rokaro", "Desolace - road toward Feralas", nil, false, {6567}, nil, "Deliver Rexxar's testament to Myranda the Hag near Uther's Tomb in Western Plaguelands.", "麦兰达(西瘟疫之地 50,77)，她会教你伪装成黑龙军团成员的办法。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 11872, "Myranda the Hag", { xp = 4950 } },
        { 6570, "H", 55, 60, "Myranda the Hag", "Western Plaguelands 50,77", nil, false, {6569}, nil, "Wear the Amulet of Draconic Subversion and speak with Emberstrife inside the cave at the southernmost tip of Dustwallow Marsh.", "Walk to the back of the cave, use the Amulet of Draconic Subversion first, then talk to Emberstrife.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10321, "Emberstrife", { xp = 4950 } },
        { 6582, "H", 55, 60, "Emberstrife", "Dustwallow Marsh - Emberstrife's Cave 56.8,87.4", nil, false, {6570}, nil, "Kill Scryer, the blue dragon in the cave of Mazthoril in Winterspring, and bring his skull back to Emberstrife.", "《颅骨试炼》三场顺序随意、可以团杀；斯克莱尔(马兹索里尔洞穴深处 53.2,56)，洞口(冬泉谷-马兹索里尔洞穴 57,50)，要清不少精英龙人。◎ 三条龙都别忘摸头骨。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10321, "Emberstrife", { xp = 6600 } },
        { 6583, "H", 55, 60, "Emberstrife", "Dustwallow Marsh - Emberstrife's Cave 56.8,87.4", nil, false, {6570}, nil, "Kill Somnus, the green dragon in Swamp of Sorrows, and bring his skull back to Emberstrife.", "索姆努斯在地图东南部大范围巡逻(约 80,70 附近)，先清一片区域等他路过。他有很强的击退，自然抗性很吃香。三场试炼顺序随意，记得摸头骨。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10321, "Emberstrife", { xp = 6600 } },
        { 6584, "H", 55, 60, "Emberstrife", "Dustwallow Marsh - Emberstrife's Cave 56.8,87.4", nil, false, {6570}, nil, "Kill Chronalis, the bronze dragon outside the Caverns of Time in Tanaris, and bring his skull back to Emberstrife.", "克罗纳利斯在时光洞穴门口(64.6,50.2)。三场试炼顺序随意、可以团杀，记得摸头骨。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10321, "Emberstrife", { xp = 6600 } },
        { 6585, "H", 55, 60, "Emberstrife", "Dustwallow Marsh - Emberstrife's Cave 56.8,87.4", nil, false, {6582, 6583, 6584}, nil, "Kill Axtroz, the red dragon in the Wetlands, and bring his skull back to Emberstrife.", "前三场颅骨试炼交完才会开放。阿克特罗兹在格瑞姆巴托附近巡逻(约 85,49)，火焰免疫；想剥皮需要剥皮技能 310。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10321, "Emberstrife", { xp = 6600 } },
        { 6601, "H", 55, 60, "Emberstrife", "Dustwallow Marsh - Emberstrife's Cave 56.8,87.4", nil, false, {6585}, nil, "Take the Dull Drakefire Amulet to Rexxar in Desolace.", "任务描述让你回黑石塔找达基萨斯将军，但伪装护符在黑石塔里不生效——直接去凄凉之地找雷克萨（巡逻路线同《部落的勇士》）。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10182, "Rokaro", { xp = 4950 } },
    },

    ["kroldok_stronghold"] = {
        { 96771, "A", 37, 45, "拉纳斯·夜路", "Alterac Mountains - 达拉然废墟 17.8,66.0", nil, false, nil, nil, "前往河林东南的克罗多克要塞，消灭与暮光之锤勾结的上层精灵扎尔凡·月影。", "接取人为奥特兰克山脉达拉然废墟鲁因维沃尔休息室的上层精灵拉纳斯·夜路（17.8,66.0）；扎尔凡·月影在克罗多克要塞内，与暮光之锤为伍、盗用奥术知识为其效力。", {{37,1}, {41,2}, {43,3}, {48,4}, {57,5}}, nil, nil, 268425, "拉纳斯·夜路", { xp = 11500, money = 6500, rep = { { 2740, 250, "Kirin Tor" }, { 2826, 150, "铁马兄弟会" } } } },
        { 94980, "A", 38, 41, "由物品[克罗多克铸件]起始", nil, nil, true, nil, nil, "在克罗多克要塞内找到可能认得这个铸模的人。", "克罗多克铸件由老二之后的怪物「吞克」（Tunk）掉落拾取即开启（像一把钥匙的铸模）；交回远霍德堡（Farholde Keep）找阿尔方斯·杜马（Alphonse Dumas），他会接着给《关键耗材》。", {{38,1}, {39,2}, {44,3}, {52,4}}, {267138}, nil, nil, nil, { xp = 3300, money = 5500 } },
        { 94981, "A", 38, 41, "阿尔方斯·杜马", "河林 - 远霍德堡 64.4,82.0", nil, false, {94980}, { 267089 }, "把 4 张厚皮和 12 块铁锭交给远霍德堡的阿尔方斯·杜马。", "前置《克罗多克铸件》：厚皮和铁锭拍卖行或剥皮/采矿都能凑；杜马照铸模开出一把钥匙。", {{38,1}, {39,2}, {44,3}, {52,4}}, {4304, 3575}, nil, 259250, "阿尔方斯·杜马", { xp = 3300, money = 5500 } },
        { 94982, "A", 40, 45, "布兰特指挥官", "河林 66.6,81.0", "远霍德堡前置三连：《拯救阳光林地》（布兰特指挥官 66.6,81.0）+《知识碎片》《奇特的饰物》（艾什·安伯霍尔 66.7,81.0）—— 三连全做完才开放本任务", false, nil, {279852, 279853, 279480}, "潜入克罗多克要塞，带回首领莫格被消灭的证据。", "布兰特指挥官（Demar Brant，河林 66.6,81.0）发放；莫格之眼由要塞首领霸主莫格（Overlord Mugg）掉落。", {{40,1}, {41,2}, {43,3}, {48,4}, {57,5}}, {267086}, nil, 257558, "布兰特指挥官", { xp = 11500, money = 13000, rep = { { 2826, 150, "铁马兄弟会" } } } },
        { 94983, "A", 38, 42, "里夫坦中士", "河林 30.6,49.1", "远霍德堡前置三连：《拯救阳光林地》（布兰特指挥官 66.6,81.0）+《知识碎片》《奇特的饰物》（艾什·安伯霍尔 66.7,81.0）—— 三连全做完才开放本任务", false, {94890}, nil, "从克罗多克要塞内的暮光之锤成员身上收集 8 个暮光手镯。", "里夫坦中士（Sergeant Riftan，河林 30.6,49.1）发放；暮光手镯由要塞内的暮光之锤成员掉落（首领暮光指挥官扎尔莫克必出）。", {{38,1}, {40,2}, {45,3}, {53,4}}, {267234}, nil, 258023, nil, { xp = 10200, rep = { { 2826, 150, "铁马兄弟会" } } }},
        { 94984, "A", 39, 44, "艾什·安伯霍尔", "河林 66.7,81.0", "远霍德堡前置三连：《拯救阳光林地》（布兰特指挥官 66.6,81.0）+《知识碎片》《奇特的饰物》（艾什·安伯霍尔 66.7,81.0）—— 三连全做完才开放本任务", false, {94907}, {279854, 279855}, "在克罗多克要塞内消灭纳古克，取回暮光宝典。", "艾什·安伯霍尔（河林 66.7,81.0）发放；暮光宝典由要塞首领纳古克（Nar'gurk）掉落，打完留意拾取。", {{39,1}, {40,2}, {42,3}, {47,4}, {56,5}}, {267104}, nil, 257591, "艾什·安伯霍尔", { xp = 11050, rep = { { 2826, 150, "铁马兄弟会" } } } },
        { 94973, "H", 38, 41, "由物品[克罗多克铸件]起始", nil, nil, true, nil, nil, "在罗格玛找一个可能认得这个铸模的人。", "部落方由「克罗多克铸件」开启：铸件由老二之后的怪物「吞克」（Tunk）掉落拾取即开启；交回罗格玛（Rog'mar）找克雷扎·暗棘（Kreza Darkthorn，59.8,46.0），她会接着给《关键耗材》。", {{38,1}, {39,2}, {44,3}, {52,4}}, {267137}, nil, nil, nil, { xp = 3300, money = 5500 } },
        { 94974, "H", 38, 41, "克雷扎·暗棘", "河林 - 罗格玛 59.8,46.0", nil, false, {94973}, { 267089 }, "把 4 张厚皮和 12 块铁锭交给罗格玛的克雷扎·暗棘。", "前置《克罗多克铸件》：厚皮和铁锭拍卖行或剥皮/采矿都能凑；暗棘照铸模开出一把钥匙（wowhead 中文站名为克雷扎·暗棘 Kreza Darkthorn）。", {{38,1}, {39,2}, {44,3}, {52,4}}, {4304, 3575}, nil, 256657, "克雷扎·暗棘", { xp = 3300, money = 5500 } },
        { 94968, "H", 40, 45, "克罗姆罗什", "河林 - 罗格玛 59.4,45.6", "河林暮光任务线：阵营营地 → 引导至食人魔 → 引导至暮光之帷 → 回城开启（含《暮光逼近》《暮光信件》《教教他们规矩》等）", false, {95278}, {279852, 279480, 279853}, "潜入克罗多克要塞，带回首领莫格被消灭的证据。", "接取与交付均为罗格玛的克罗姆罗什（59.4,45.6；wowhead 任务页地图标记与任务描述「return to Krom'rosh」双证）；莫格之眼由要塞首领霸主莫格（Overlord Mugg）掉落。", {{40,1}, {41,2}, {43,3}, {48,4}, {57,5}}, {267086}, nil, 256418, "克罗姆罗什", { xp = 11500, money = 13000 } },
        { 94975, "H", 38, 42, "达格罗什", "河林 - 罗格玛以西山地 33.4,38.0", nil, false, {94768}, { 267090 }, "从克罗多克要塞内的暮光之锤成员身上收集 15 只教徒的耳朵。", "接取与交付均为达格罗什—— 他就是《任性的战士》让你去罗格玛以西山地找的那位，做完才会开放本任务；教徒的耳朵由要塞内的暮光之锤成员掉落（首领暮光指挥官扎尔莫克必出）；描述提到北边的洞穴里还藏着更多教徒。", {{38,1}, {40,2}, {45,3}, {53,4}}, {267091}, nil, 258570, nil, { xp = 8200 }},
        { 94972, "H", 39, 44, "特兰古尔", "河林 59.4,44.2", "河林暮光任务线：阵营营地 → 引导至食人魔 → 引导至暮光之帷 → 回城开启（含《暮光逼近》《暮光信件》《教教他们规矩》等）", false, {95278}, {279859, 279860}, "从克罗多克要塞取回暮光宝典。", "特兰古尔（Trangul，罗格玛营地 59.4,44.2；wowhead 任务页标注起止均为他，此前沿用的「指挥官阿格罗戈什」是指南链错的荆棘谷 NPC）发放；宝典由要塞首领纳古克（Nar'gurk）掉落。", {{39,1}, {40,2}, {42,3}, {47,4}, {56,5}}, {267104}, nil, 256710, "特兰古尔", { xp = 11050 } },
    },
    ["blackmaw_hold"] = {
        { 92344, "A", 45, 55, "Mathrengyl Bearwalker", "Darnassus 34.8,7.4", nil, false, {92345}, nil, "在黑喉要塞内收集 10 个诺达希尔根帽，交给达纳苏斯的玛斯雷·驭熊者。", "先在艾萨拉飞行点旁找指挥官真歌接《诺达希尔之底》，到达纳苏斯塞纳里奥区找玛斯雷·驭熊者交，才会接到本任务。诺达希尔根帽只在要塞地下的新根上出（地表的老根不算），五人队要凑 50 个，好在要塞够大、拾取后还会刷新；凑 10 个回达纳苏斯交给玛斯雷·驭熊者。", {{45,1}, {51,2}, {53,3}, {58,4}}, {250773}, nil, 4217, nil, { xp = 11300, rep = { { 69, 150, "Darnassus" } } }},
        { 92343, "H", 45, 55, "Nara Wildmane", "Thunder Bluff 75,31", nil, false, {92346}, nil, "在黑喉要塞内收集 10 个诺达希尔根帽，交给雷霆崖的纳拉·蛮鬃。", "先在艾萨拉找杰迪加接《诺达希尔之底》，到雷霆崖长者高地找纳拉·蛮鬃交，才会接到本任务。诺达希尔根帽只在要塞地下的新根上出（地表的老根不算），五人队要凑 50 个，好在要塞够大、拾取后还会刷新；凑 10 个回雷霆崖交给纳拉·蛮鬃（75,31）。", {{45,1}, {51,2}, {53,3}, {58,4}}, {250773}, nil, 5770, nil, { xp = 11300, rep = { { 81, 150, "Thunder Bluff" } } }},
        { 92069, nil, 45, 58, "奥汀克", "Azshara - 埃达拉斯废墟 42.4,42.6", nil, false, nil, {260213, 260214, 260215}, "把巨熊之爪和不屈者之牙带回艾萨拉，交给奥汀克。", "巨熊之爪出自湖畔石窟深处的枯颌（Withermaw），不屈者之牙出自横贯山谷里巡行的不屈的白骨之吻（Bonesnout）；两件都带回艾萨拉埃达拉斯废墟上方的悬崖，交给奥汀克（42.4,42.6）做成纪念品。", {{45,1}, {54,2}, {56,3}}, {249697, 249696}, nil, 8405, "奥汀克", { xp = 12400, rep = { { 576, 150, "木喉要塞" } } }},
        { 92066, nil, 47, 55, "博学者诺克", "Azshara - 乌索兰 41.4,20.0", nil, false, nil, {279891, 279892}, "在黑喉要塞内找到乌索克的图腾和乌索尔的图腾，带回乌索兰交给博学者诺克。", "木喉要塞声望必须到中立，乌索兰的博学者诺克才会给这条任务。两座熊神图腾都留在黑喉要塞里：乌索克的在五号首领房间、与首领相对的那面墙边，乌索尔的在六号首领房间门外的墙边；进本一路留意拾取，凑齐后回艾萨拉的乌索兰（41.4,20.0）交给博学者诺克。", {{47,1}, {51,2}, {53,3}, {58,4}}, {249694, 249693}, nil, 249853, "博学者诺克", { xp = 11300, rep = { { 576, 150, "木喉要塞" } } }},
        { 97173, "A", 52, 59, "大法师提迈尔", "Alterac Mountains 15.4,74.1", nil, false, nil, nil, "从黑喉要塞取回一个黑喉仪祭图腾。", "接取与交付均为奥特兰克山脉达拉然废墟的大法师提迈尔（15.4,74.1）；黑喉仪祭图腾由长者萨满血鬃（Elder Shaman Bloodmane）等最强的黑喉萨满携带。", {{52,1}, {55,2}, {57,3}}, {276893}, nil, 31439, "大法师提迈尔", { xp = 12800, money = 9000, rep = { { 2740, 300, "Kirin Tor" }, { 69, 150, "Darnassus" } } }},
        { 97198, "H", 52, 59, "穆恩·大地之怒", "Mulgore 33.4,22.6", nil, false, nil, nil, "从黑喉要塞取回一个黑喉仪祭图腾。", "部落方同名任务：接取与交付均为穆恩·大地之怒（莫高雷 33.4,22.6）；黑喉仪祭图腾由长者萨满血鬃（Elder Shaman Bloodmane）等最强萨满携带。", {{52,1}, {55,2}, {57,3}}, {276893}, nil, 259118, "穆恩·大地之怒", { xp = 16100, money = 9000, rep = { { 2787, 300, "大地之环" }, { 81, 150, "Thunder Bluff" } } }},
        { 92070, nil, 47, 55, "由物品[羽饰护符项链]起始", nil, nil, true, nil, {249698}, "找到羽饰护符项链的主人。", "在黑喉要塞内拾取「羽饰护符项链」自动接到，无需找 NPC 接取：这是一条物品起始的任务，项链由要塞里的黑喉族掉落；按任务指引把项链交还失主即可，交还 NPC 以任务追踪界面为准。", {{47,1}, {51,2}, {53,3}, {58,4}}, {249698}, nil, nil, nil, { xp = 11300, rep = { { 576, 100, "木喉要塞" } } }},
        { 92065, nil, 55, 60, "拉格罗尔", "Azshara - 乌索兰 41.4,20.0", nil, false, {86814}, {249692}, "把瓦罗克斯·暗蹄的头颅交给乌索兰的护门者拉格罗尔。", "木喉要塞声望必须到中立，乌索兰的护门者拉格罗尔才会给这条长链；埃卡尔的《黑喉袋子》交完后那条在艾萨拉杀 15 个萨特的后续也得做完。之后先在艾萨拉把《菲达雷德》《削减兵力》《萨特，回头见》三条都做完，找拉格罗尔交《向拉格罗尔复命》，再依次做《木喉的增援》《血喉酋长》《黑喉的反攻》才能接到本任务；进黑喉要塞杀瓦罗克斯·暗蹄取头颅，回乌索兰交给护门者拉格罗尔。", {{55,1}, {56,2}, {58,3}, {60,4}}, {249692}, nil, 6651, "拉格罗尔", { xp = 13200, rep = { { 576, 150, "木喉要塞" } } }},
        { 97327, nil, 55, 60, "埃卡尔", "Azshara - 埃达拉斯废墟 42.0,38.8", nil, false, nil, nil, "进入黑喉要塞，取回 5 个黑喉袋子，交给艾萨拉埃达拉斯废墟的埃卡尔。", "黑喉袋子由要塞内被腐化的黑喉族同胞掉落，凑 5 个；这东西不绑定，嫌麻烦可以直接在拍卖行买。交回艾萨拉埃达拉斯废墟的埃卡尔（42.0,38.8）后，他还会给一条在艾萨拉杀 15 个萨特的后续，那是《光复黑喉》的前置之一。", {{55,1}, {56,2}, {58,3}}, {273050}, nil, 235903, "埃卡尔", { xp = 13200, money = 9000, rep = { { 576, 150, "木喉要塞" } } }},
    },
    ["shapers_terrace"] = {
        { 95924, "A", 55, 60, nil, "Ironforge 64.4,4.0", nil, false, nil, {279903, 279905}, "消灭毒脊，并击杀 6 只掠暴龙母兽和 8 只铁鳞掠暴龙。", "发布者为塑造者平台外挖掘营地的一位矮人（名字暂缺）；毒脊是首领级掠暴龙，母兽与铁鳞沿路成群，一趟清完。", {{55,1}, {56,2}, {58,3}}, nil, nil, 8256, nil, { xp = 17650, money = 9000, rep = { { 47, 100, "Ironforge" }, { 72, 50, "Stormwind City" } } }},
        { 95925, "A", 55, 60, nil, "Ironforge 64.4,4.0", nil, false, nil, {279908, 279910, 279912}, "在塑造者平台找到五处地点并在探险地图上做标记：同化之柱、无色水晶、西部大门、愈合前厅、出土的石头卫士。", "与《挖掘场的恐慌》在同一处营地接；五个地点进本绕一圈即可点完，先探到哪个点哪个。", {{55,1}, {56,2}, {58,3}}, nil, nil, 8256, nil, { xp = 17650, rep = { { 47, 100, "Ironforge" }, { 72, 50, "Stormwind City" } } }},
        { 95928, "H", 55, 60, "玛耶娜·寻地者", "莫高雷 34.8,22.0", nil, false, nil, {279904, 279906}, "把炽热的水晶、充能的水晶、有毒的水晶和潮湿的水晶各一个带给玛耶娜·寻地者。", "玛耶娜·寻地者要四种水晶：炽热、充能、有毒、潮湿各 1 个，全在要塞内的元素怪身上出；接取与交付为同一人。", {{55,1}, {56,2}, {58,3}}, {271894, 271898, 271902, 271912}, nil, 263445, nil, { xp = 17650, rep = { { 76, 50, "Orgrimmar" }, { 2787, 100, "大地之环" } } }},
        { 97049, "H", 55, 60, nil, "Undercity 47.4,72.4", nil, false, nil, {279932, 279902}, "收集 8 份渗漏的软泥怪精华。", "渗漏的软泥怪精华由无色水晶旁水池里的软泥怪掉落，凑 8 份；接取与交付为同一 NPC（名字暂缺，与《晶化元素》同在平台外）。", {{55,1}, {56,2}, {58,3}}, {276235}, nil, 10136, nil, { xp = 17650, money = 9000, rep = { { 68, 100, "Undercity" }, { 76, 50, "Orgrimmar" } } }},
        { 95926, "H", 55, 60, nil, "Undercity 48.4,68.0", nil, false, nil, {279908, 279910, 279912}, "在无色水晶附近收集一份枯竭的水晶碎片。", "无色水晶（Achromatic Crystal）就在平台深处，碎片在它附近的地面上拾取；也是《绘制前路》要标记的地点之一，顺路一起做。", {{55,1}, {56,2}, {58,3}}, nil, nil, 2055, nil, { xp = 6600, rep = { { 68, 100, "Undercity" }, { 76, 50, "Orgrimmar" } } }},
        { 95790, "A", 55, 60, nil, nil, nil, true, nil, nil, "前往塑造者之台，收集 15 张消化了一半的日记书页。", "日记被掠暴龙撕碎，书页散落在台内；拾取第一张就会接到本任务，没有接取 NPC，凑满 15 张当场完成，不用出本复命。书页是普通品质的任务物品，可叠 20 张。日记原主是探险者协会的一位冒险者，封皮边缘的咬痕说明是掠暴龙干的。", {{55,1}, {56,2}, {58,3}}, {271972}, nil, nil, nil, { xp = 17655, rep = { { 47, 100, "Ironforge" }, { 72, 100, "Stormwind" } } } },
    },
}

