function ns.EnsureDungeonQuestExtInfo()
    ns.EnsureDungeonQuestExtInfo = function() return ns.DungeonQuestExtInfo end
    if ns.DungeonQuestExtInfo then return ns.DungeonQuestExtInfo end
    ns.DungeonQuestExtInfo = {
    [203] = { lv = 30, lvStd = 33, nm = "以彼之道还施彼身", npc = "尤瓦中士", npcid = 733, side = "A", zone = "Stranglethorn Vale", goals = { { "o", "杀死 15 名库尔森丛林战士" } }, obj = "杀死 15 名库尔森丛林战士，然后向荆棘谷反抗军营地的尤瓦中士复命。", text = "尤瓦中士在荆棘谷的反抗军营地（38.0,3.3），与《库尔森的药物》一起给：库尔森的兵力是反抗军的十倍，照他的打法还手——进东边营地把丛林战士杀够 15 个，增援赶来之前撤出。", gains = { xp = 1950, rep = { { 72, 75, "Stormwind City" } } } },
    [204] = { lv = 30, lvStd = 34, nm = "库尔森的药物", npc = "尤瓦中士", npcid = 733, side = "A", zone = "Stranglethorn Vale", goals = { { "i", 2633, 7 }, { "i", 2634, 1 } }, obj = "给反抗军营地的尤瓦中士带回 7 份密林药剂和 1 份毒草汁液。", text = "与《以彼之道还施彼身》同在尤瓦中士处接：密林药剂要从库尔森营地的医疗人员身上拿，毒草汁液存在营地的物资箱里；两条都交完，尼麦兹修士才会给《库尔森的秘密》。", gains = { xp = 2700, rep = { { 72, 100, "Stormwind City" } } } },
    [205] = { lv = 30, lvStd = 40, npc = "尼麦兹修士", npcid = 739, side = "A", zone = "Stranglethorn Vale", pre = { 207 }, obj = "从劈颅巨魔的巫医和秘法师身上收集 4 只劈颅巨魔的神像，交给荆棘谷的尼麦兹修士。", text = "联盟沉没之城引导链的最后一环：完成它之后，就能在南海镇（希尔斯布莱德丘陵 50.6,57.1）的博学者迪布斯处接《就水服下两片》与《沉没之城的魔法》。", gains = { xp = 3150, rep = { { 72, 100, "Stormwind City" } } } },
    [207] = { lv = 30, lvStd = 38, npc = "尼麦兹修士", npcid = 739, side = "A", zone = "Stranglethorn Vale", pre = { 203, 204 }, obj = "把四块巨魔石板上的拓片交给尼麦兹修士：巴拉尔废墟、暗礁海海底、祖昆达废墟。", text = "联盟沉没之城引导链的第 3 环：先在反抗军营地把尤瓦中士的《以彼之道还施彼身》与《库尔森的药物》都交掉，尼麦兹修士才会给这条拓片任务；第一块石板在巴拉尔废墟，第二块在暗礁海海底，第三、第四块都在祖昆达废墟，拓齐一并交回。", gains = { xp = 3550, rep = { { 72, 150, "Stormwind City" } } } },
    [95786] = { lv = 30, lvStd = 40, nm = "南海镇的熟人", npc = "尼麦兹修士", npcid = 739, side = "A", zone = "Stranglethorn Vale", pre = { 205 }, obj = "带着尼麦兹修士的引荐去南海镇，找博学者迪布斯谈一谈。", text = "林荫旅店门口的博学者迪布斯在希尔斯布莱德丘陵的南海镇（50.6,57.1），交掉之后他就会给两条副本任务。", gains = { xp = 3150, rep = { { 72, 100, "Stormwind City" }, { 67, 100, "[UNUSED] Brother Milius" } } } },
    [95748] = { lv = 30, lvStd = 40, npc = "肯维雷（32.2,27.8）", npcid = 2519, side = "H", zone = "Stranglethorn Vale", pre = { 629 }, obj = "听肯维雷讲古拉巴什传说，去祖昆达废墟给石板做拓片后回禀。", text = "格罗姆高营地三环的第 2 环：接完《暗礁海》后在肯维雷处接，带兽皮和木炭去北边祖昆达废墟拓印。" },
    [95770] = { lv = 30, lvStd = 40, npc = "肯维雷", npcid = 2519, side = "H", zone = "Stranglethorn Vale", pre = { 95748 }, obj = "去暗礁海西边的洞口探一圈，回格罗姆高营地复命。", text = "格罗姆高营地三环的最后一环：复命后即可接副本任务《沉没之城》。" },
    [95789] = { lv = 34, lvStd = 40, npc = "Krazek", npcid = 773, zone = "Stranglethorn Vale", obj = "收集 10 个注入巫毒的神器，交给藏宝海湾的克拉兹克。", text = "双阵营都可接：克拉兹克在藏宝海湾旅店三层（27.0,77.2）；注入巫毒的神器由副本内盐水先知施法者掉落。", rew = { 279882, 279930 }, gains = { xp = 10450, rep = { { 21, 100, "Booty Bay" }, { 470, 50, "Ratchet" }, { 369, 50, "Gadgetzan" }, { 577, 50, "Everlook" } } } },
    [95791] = { lv = 34, lvStd = 40, npc = "克拉兹克（27.0,77.2）", npcid = 773, zone = "Stranglethorn Vale", pre = { 95789 }, obj = "消灭德雷德莱斯船长和盐水先知验尸官，回藏宝海湾复命。", text = "双阵营都可接：船长是副本首领之一，验尸官沿路成群；与《可疑的盐水先知》同在克拉兹克处接。", rew = { 279883, 279884 }, gains = { xp = 10450, rep = { { 21, 100, "Booty Bay" }, { 369, 50, "Gadgetzan" }, { 577, 50, "Everlook" }, { 470, 50, "Ratchet" } } } },
    [97130] = { lv = 34, lvStd = 40, npc = "大法师提迈尔", npcid = 31439, side = "A", zone = "Alterac Mountains", obj = "取回上古古拉巴什神像，交给达拉然废墟的大法师提迈尔。", text = "提迈尔在奥特兰克山脉的达拉然废墟（15.6,73.6）；神像由不死骨髓一战掉落，与部落的《上古古拉巴什神像》共用目标。", gains = { xp = 10450, rep = { { 2740, 300, "Kirin Tor" }, { 72, 150, "Stormwind City" } } } },
    [17] = { rew = { 250947 }, gains = { xp = 6050, rep = { { 47, 100, "Ironforge" } } } },
    [65] = { lv = 14, lvStd = 18, nm = "Red Silk Bandanas", npc = "格里安·斯托曼（56.2,47.4）", npcid = 234, side = "A", zone = "Westfall", gains = { xp = 1350, rep = { { 72, 100, "Stormwind City" } } }, obj = "格里安·斯托曼要求你去和湖畔镇的威利谈一谈。", text = "在西部荒野哨兵岭找格里安·斯托曼接取；去湖畔镇旅店与黑衣威利搭话，问出迪菲亚的下落。" },
    [132] = { lv = 14, lvStd = 18, nm = "Red Silk Bandanas", npc = "黑衣威利（21.4,45.2）", npcid = 266, side = "A", zone = "Westfall", goals = { { "i", 1327, 1 } }, gains = { xp = 680, rep = { { 72, 50, "Stormwind City" } } }, obj = "将威利的便笺交给西部荒野的格里安·斯托曼。", text = "从湖畔镇的黑衣威利拿到便笺，返回西部荒野哨兵岭交给格里安·斯托曼。" },
    [135] = { lv = 14, lvStd = 18, nm = "Red Silk Bandanas", npc = "Marshal Gryan Stoutmantle", npcid = 234, side = "A", zone = "Westfall", goals = { { "i", 1327, 1 } }, gains = { xp = 680, rep = { { 72, 50, "Stormwind City" } } }, obj = "将威利的便笺交给暴风城的马迪亚斯·肖尔。", text = "把威利的便笺送到暴风城旧城区兵营，交给军情七处的马迪亚斯·肖尔。" },
    [141] = { lv = 14, lvStd = 18, nm = "Red Silk Bandanas", npc = "Mathias Shaw", npcid = 332, side = "A", zone = "Westfall", goals = { { "i", 1353, 1 } }, gains = { xp = 340, rep = { { 72, 25, "Stormwind City" } } }, obj = "将肖尔的报告交给西部荒野的格里安·斯托曼。", text = "拿到肖尔的报告后回到西部荒野哨兵岭，交给格里安·斯托曼。" },
    [142] = { lv = 14, lvStd = 18, nm = "Red Silk Bandanas", npc = "Marshal Gryan Stoutmantle", npcid = 234, side = "A", zone = "Westfall", goals = { { "i", 1381, 1 } }, gains = { xp = 1350, rep = { { 72, 100, "Stormwind City" } } }, obj = "追捕西部荒野的迪菲亚信使，并将他身上携带着的信件交给斯托曼。", text = "在月溪镇、金海岸矿洞、詹戈洛德矿洞之间的路上蹲守迪菲亚信使，击杀后把搜到的信件交回哨兵岭。" },
    [155] = { lv = 14, lvStd = 18, nm = "Red Silk Bandanas", npc = "迪菲亚叛徒（43.1,70.2）", npcid = 467, side = "A", zone = "Westfall", gains = { xp = 1700, rep = { { 72, 150, "Stormwind City" } } }, obj = "护送迪菲亚叛徒前往迪菲亚兄弟会的秘密藏身处。迪菲亚叛徒把你带到范克里夫和他的手下的巢穴之后，尽快回去向格里安·斯托曼汇报相关信息。", text = "护送迪菲亚叛徒前往月溪镇的迪菲亚藏身处，他会带路，路上别让他死；抵达后回哨兵岭向斯托曼复命。" },
    [261] = { pre = { 6141 }, gains = { xp = 3000 } },
    [303] = { gains = { xp = 2450, rep = { { 47, 100, "Ironforge" } } } },
    [373] = { lv = 16, lvStd = 22, nm = "未寄出的信", npc = "未寄出的信", zone = "Stormwind City", si = true, goals = { { "i", 2874, 1 } }, gains = { xp = 2066, money = 700, rep = { { 72, 50, "Stormwind City" } } }, obj = "将艾德温·范克里夫的信交给巴隆斯·阿历克斯顿。", side = "A" },
    [389] = { lv = 16, lvStd = 22, nm = "The Stockade Riots", npc = "巴隆斯·阿历克斯顿（49.0,30.2）", npcid = 1646, side = "A", zone = "Stormwind City", gains = { xp = 435 }, obj = "与监狱的典狱官塞尔沃特谈一谈。", text = "前置做完《迪菲亚兄弟会》链后在暴风城找巴隆斯·阿历克斯顿接取；进暴风城监狱找典狱官塞尔沃特对话即可。" },
    [356] = { lv = 6, lvStd = 11, nm = "巡查后方", npc = "亡灵卫兵林奈", npcid = 1495, side = "H", zone = "Tirisfal Glades", goals = { { "o", "杀死 8 个可怕的血僵尸" }, { "o", "杀死 8 个游荡的幽灵" } }, gains = { xp = 660, rep = { { 68, 75, "Undercity" } } }, obj = "杀死8个可怕的血僵尸和8个游荡的幽灵，然后向亡灵卫兵林奈汇报。", text = "林奈在布瑞尔，两批任务怪都在城外一带，清完回去交。" },
    [447] = { lv = 9, lvStd = 12, nm = "致命的配方", npc = "药剂师伦弗利尔", npcid = 1937, side = "H", zone = "Silverpine Forest", goals = { { "i", 3253, 6 }, { "i", 3254, 6 } }, gains = { xp = 910, rep = { { 68, 100, "Undercity" } } }, obj = "收集6个灰熊的心脏和6份粘稠的血液样本，并将这些东西送给幽暗城的大药剂师法拉尼尔。", text = "从瑟伯切尔的伦弗利尔处接，灰熊心脏和粘稠的血液都在银松森林一带打，凑齐后进幽暗城交给法拉尼尔。", rew = { 3448 } },
    [450] = { lv = 9, lvStd = 15, nm = "致命的配方", npc = "Master Apothecary Faranell", npcid = 2055, side = "H", zone = "Silverpine Forest", goals = { { "i", 3255, 1 } }, gains = { xp = 1350, rep = { { 68, 150, "Undercity" } } }, pre = { 447 }, obj = "从焚木村的旅店中找到伯纳德的日记，把它交给瑟伯切尔的药剂师伦弗利尔。", text = "日记在焚木村旅店里，拿到后回瑟伯切尔交给伦弗利尔。" },
    [451] = { lv = 9, lvStd = 18, nm = "致命的配方", npc = "药剂师伦弗利尔", npcid = 1937, side = "H", zone = "Silverpine Forest", goals = { { "i", 3256, 6 }, { "i", 3257, 6 }, { "i", 3258, 1 } }, gains = { xp = 2050, rep = { { 68, 200, "Undercity" } } }, pre = { 450 }, obj = "收集6份湖岸爬行者苔藓的样本、6份湖岸潜藏者苔藓的样本和1块硬瘤，把它们交给幽暗城的大药剂师法拉尼尔。", text = "两种湖岸苔藓在瑟伯切尔北边的湖岸采，硬瘤从湖边软泥怪身上出，凑齐后回幽暗城交。", rew = { 3451, 3582, 276723, 2458, 2459 } },
    [469] = { lv = 18, lvStd = 21, nm = "日常供货", npc = "埃纳尔·石钳（49.8,39.4）", npcid = 2093, side = "A", zone = "Wetlands", goals = { { "i", 3347, 1 } }, gains = { xp = 830, money = 700, rep = { { 72, 50, "Stormwind City" } } }, obj = "将这捆鳄鱼皮带给米奈希尔港的皮匠詹姆斯·哈洛兰。", text = "在湿地米奈希尔港外找埃纳尔·石钳接取，把这捆鳄鱼皮带进港内交给皮匠詹姆斯·哈洛兰。" },
    [629] = { lv = 30, lvStd = 37, nm = "暗礁海", npc = "肯维雷", npcid = 2519, side = "H", zone = "Stranglethorn Vale", obj = "给格罗姆高营地里的肯维雷带回一块石板碎片。", text = "潜到暗礁海的水下废墟，从大石板上敲一块碎片带回格罗姆高营地。", gains = { xp = 2850, rep = { { 530, 100, "Darkspear Trolls" } } } },
