    [92742] = { lv = 9, lvStd = 12, nm = "测试水井", npc = "阿尔巴·晴月（52.4,53.0）", npcid = 253092, zone = "Westfall", goals = { { "i", 254546, 1 }, { "i", 254547, 1 }, { "i", 254545, 1 } }, gains = { xp = 455, money = 250, rep = { { 72, 50, "Stormwind City" } } }, obj = "使用井水采样工具包，从詹森农场和莫尔森农场的水井中采集样本。", text = "在西部荒野找阿尔巴·晴月接；带井水采样工具包到詹森农场和莫尔森农场的水井取样，两处都要采。", side = "A" },
    [92744] = { lv = 9, lvStd = 12, nm = "鱼人的鳃", npc = "阿尔巴·晴月（52.4,53.0）", npcid = 253092, zone = "Westfall", goals = { { "i", 254548, 7 } }, gains = { xp = 455, money = 250, rep = { { 72, 50, "Stormwind City" } } }, obj = "阿尔巴·晴月要你在西部荒野海岸沿线收集7份长岸鱼人鳃。", text = "沿西部荒野海岸线猎杀长岸鱼人，凑齐 7 份鱼人鳃交给阿尔巴·晴月。", side = "A" },
    [92745] = { lv = 9, lvStd = 14, nm = "矿洞近况", npc = "Alba Fairmoon", npcid = 253092, zone = "Westfall", goals = { { "c", "狗头人掘地工", 4 }, { "c", "河爪矿工", 6 } }, gains = { xp = 490, money = 300, rep = { { 72, 50, "Stormwind City" } } }, obj = "在詹戈洛德矿洞消灭4名狗头人掘地工，并在金海岸矿洞消灭6名河爪矿工。", text = "进詹戈洛德矿洞杀 4 名狗头人掘地工，再去金海岸矿洞杀 6 名河爪矿工，打完回阿尔巴处。", side = "A" },
