    [1394] = { lv = 26, lvStd = 32, npc = "Parqual Fintallas", npcid = 4488, zone = "Undercity", obj = "和千针石林的多恩·平原行者谈一谈。", text = "帕科瓦·芬塔拉斯在幽暗城（57.4,65.4）。完成后去找多恩·平原行者（千针石林）。" },
    [2439] = { lv = 40, lvStd = 43, npc = "High Explorer Magellas", npcid = 5387, zone = "Ironforge", obj = "把你的报酬凭证交给铁炉堡银行的丁尼塔·石衣。", text = "资深探险家麦格拉斯在铁炉堡（69.0,19.6）。完成后去找丁尼塔·石衣（铁炉堡）。" },
    [2440] = { lv = 40, lvStd = 43, npc = "Sage Truthseeker", npcid = 3978, zone = "Thunder Bluff", obj = "把报酬凭证交给雷霆崖的本娜·冰蹄。", text = "圣者图希克在雷霆崖（34.4,47.2）。完成后去找本娜·冰蹄（雷霆崖）。" },
    [2948] = { lv = 28, lvStd = 31, npc = "Talvash del Kissel", npcid = 6826, zone = "Ironforge", obj = "将闪亮的金戒指、1块银锭、1块绿玛瑙和30个银币交给铁炉堡的塔瓦斯德·基瑟尔。", text = "塔瓦斯德·基瑟尔在铁炉堡（36.0,3.4）。" },
    [2953] = { lv = 25, lvStd = 30, npc = "Super Cleaner 5200", zone = "Gnomeregan", obj = "超级清洁器5200型等待着清理脏兮兮的东西，它需要三枚银币才能启动！", text = "超级清洁器5200型在诺莫瑞根。" },
    [3369] = { lv = 10, lvStd = 21, npc = "菲拉·古风", npcid = 8418, zone = "The Barrens", obj = "把噩梦碎片交给长者高地的哈缪尔·符文图腾。", text = "菲拉·古风在贫瘠之地（48.2,32.8）。完成后去找大德鲁伊哈缪尔·符文图腾（雷霆崖）。" },
    [3375] = { lv = 37, lvStd = 38, npc = "Talvash del Kissel", npcid = 6826, zone = "Ironforge", obj = "把一瓶法力药水、一块煤和一瓶蜂蜜酒送到铁炉堡的塔瓦斯德·基瑟尔那里，用以换取塔瓦斯德的占卜之瓶。", text = "塔瓦斯德·基瑟尔在铁炉堡（36.0,3.4）。" },
    [4148] = { lv = 47, lvStd = 49, npc = "Larion", npcid = 9118, zone = "Un'Goro Crater", obj = "收集血瓣花苗，交给安戈洛环形山的拉瑞安。", text = "拉瑞安在安戈洛环形山（45.4,8.4）。" },
    [4295] = { lv = 1, lvStd = 1, npc = "罗克诺特下士", npcid = 9503, zone = "Blackrock Depths", obj = "哦，酒！为了黑铁矮人的酒，我甚至愿意去杀人！快点，我的酒劲正在消退！我的视线越来越模糊了……你看上去越来越像上个星期我干掉的那个&lt;race&gt;了！", text = "罗克诺特下士在黑石深渊。" },
    [5063] = { lv = 57, lvStd = 58, npc = "玛雷弗斯的目录", zone = "Winterspring", obj = "为了制造血色学者之帽，你必须将下列物品交给玛雷弗斯·暗锤：1块比斯巨兽的皮，5根磨损的憎恶缝合线，8块奥术水晶，5根魔化红线。", text = "玛雷弗斯的目录在冬泉谷（61.0,38.8）。完成后去找玛雷弗斯·暗锤（冬泉谷）。" },
    [5067] = { lv = 57, lvStd = 58, npc = "玛雷弗斯的目录", zone = "Winterspring", obj = "为了制造阿卡纳护腿，你必须将下列物品交给玛雷弗斯·暗锤：1块比斯巨兽的皮，5根磨损的憎恶缝合线，5块奥金锭，5份莱斯·霜语的防腐液。", text = "玛雷弗斯的目录在冬泉谷（61.0,38.8）。" },
    [5068] = { lv = 57, lvStd = 58, npc = "玛雷弗斯的目录", zone = "Winterspring", obj = "为了制造嗜血胸甲，你必须将下列物品交给玛雷弗斯·暗锤：1块比斯巨兽的皮，10根磨损的憎恶缝合线，5块奥金锭，5块暗影之皮。", text = "玛雷弗斯的目录在冬泉谷（61.0,38.8）。完成后去找玛雷弗斯·暗锤（冬泉谷）。" },
    [5122] = { lv = 55, lvStd = 56, npc = "Aurius", npcid = 10917, zone = "Stratholme", obj = "取回信仰奖章，交给斯坦索姆的奥里克斯。", text = "奥里克斯在斯坦索姆。" },
    [5265] = { lv = 55, lvStd = 56, npc = "玛克斯韦尔·泰罗索斯男爵", npcid = 11034, zone = "Eastern Plaguelands", obj = "打开银色黎明宝箱，拿取你应得的奖励。", text = "玛克斯韦尔·泰罗索斯男爵在东瘟疫之地（81.4,58.0）。" },
    [5342] = { lv = 52, lvStd = 56, npc = "Alexi Barov", npcid = 11022, zone = "Tirisfal Glades", obj = "到冰风岗——联盟的领地——去暗杀维尔顿·巴罗夫。把他的脑袋交给阿莱克斯·巴罗夫。", text = "阿莱克斯·巴罗夫在提瑞斯法林地（83.0,71.4）。" },
    [5344] = { lv = 52, lvStd = 56, npc = "Weldon Barov", npcid = 11023, zone = "Western Plaguelands", obj = "去亡灵壁垒——部落的领地——去暗杀阿莱克斯·巴罗夫。把他的脑袋交给维尔顿·巴罗夫。", text = "维尔顿·巴罗夫在西瘟疫之地（43.4,83.4）。" },
    [6804] = { lv = 55, lvStd = 59, npc = "Duke Hydraxis", npcid = 13278, zone = "Azshara", obj = "对东瘟疫之地的被感染的水元素使用海神之水。把12副不谐护腕和海神之水交给艾萨拉的海达克西斯公爵。", text = "海达克西斯公爵在艾萨拉（79.2,73.4）。" },
    [7483] = { lv = 58, lvStd = 60, npc = "Lorekeeper Lydros", npcid = 14368, zone = "Dire Maul", pre = {7481, 7482}, obj = "将急速圣典、1块原始黑钻石、2份大块魔光碎片和2份英雄之血交给厄运之槌的博学者莱德罗斯，以换取一份急速秘药。", text = "博学者莱德罗斯在厄运之槌。", gains = { xp = 1650, rep = { { 809, 200, "Shen'dralar" } } } },
    [7484] = { lv = 58, lvStd = 60, npc = "Lorekeeper Lydros", npcid = 14368, zone = "Dire Maul", pre = {7481, 7482}, obj = "将专注圣典、1块原始黑钻石、4份大块魔光碎片和2张暗影之皮交给厄运之槌的博学者莱德罗斯，以换取一份专注秘药。", text = "博学者莱德罗斯在厄运之槌。", gains = { xp = 3300, rep = { { 809, 200, "Shen'dralar" } } } },
    [7485] = { lv = 58, lvStd = 60, npc = "Lorekeeper Lydros", npcid = 14368, zone = "Dire Maul", pre = {7481, 7482}, obj = "将防护圣典、1块原始黑钻石、2份大块魔光碎片和1份磨损的憎恶缝合线交给厄运之槌的博学者莱德罗斯，以换取一份防护秘药。", text = "博学者莱德罗斯在厄运之槌。", gains = { xp = 1650, rep = { { 809, 200, "Shen'dralar" } } } },
    [7509] = { lv = 60, lvStd = 63, npc = "Lorekeeper Lydros", npcid = 14368, zone = "Dire Maul", obj = "你必须设法让奥妮克希亚对这把未淬火的的上古之刃喷射火焰。完成之后，捡起加热过的上古之刃。你要注意的是，加热过的上古之刃不会一直保持被加热的状态，时间非常紧迫。", text = "博学者莱德罗斯在厄运之槌。" },
    [7638] = { lv = 60, lvStd = 63, npc = "Duthorian Rall", npcid = 6171, zone = "Stormwind City", obj = "与暴风城教堂区的格雷森·沙东布瑞克公爵谈一谈。", text = "达索瑞恩·拉尔在暴风城（39.4,30.6）。完成后去找格雷森·沙东布瑞克公爵（暴风城）。" },
    [8996] = { lv = 58, lvStd = 63, npc = "瓦塔拉克公爵之魂", npcid = 16073, zone = "Dire Maul: North", obj = "回到黑石山的伯德雷那里去，把召唤火盆交给他。", text = "瓦塔拉克公爵之魂在厄运之槌 北。完成后去找伯德雷。" },
    [92345] = { lv = 45, lvStd = 55, npc = "指挥官真歌", npcid = 239822, side = "A", zone = "Azshara", obj = "前往达纳苏斯的塞纳里奥区，与玛斯雷·驭熊者谈一谈。", text = "诺达希尔之下系列（联盟）第一环：指挥官真歌在艾萨拉飞行点旁（11.8,78.2），接完到达纳苏斯塞纳里奥区找玛斯雷·驭熊者（35.4,8.4）交，交完接《追根溯源》。" },
    [92346] = { lv = 45, lvStd = 55, npc = "杰迪加", npcid = 8587, side = "H", zone = "Azshara", obj = "前往雷霆崖的长者高地，与纳拉·蛮鬃谈一谈。", text = "诺达希尔之下系列（部落）第一环：杰迪加在艾萨拉（22.6,51.4），接完去雷霆崖长者高地找纳拉·蛮鬃（75.7,31.6）交，交完接《追根溯源》。" },
    [94907] = { lv = 36, lvStd = 44, npc = "艾什·安伯霍尔", npcid = 257591, side = "A", zone = "河林", obj = "在河林抓住一个暮光信徒，把它带回法霍尔德堡给艾什·安伯霍尔。", text = "河林引导系列（两环）的第一环：艾什·安伯霍尔在法霍尔德堡（66.6,81.0），接取与上交都在她这里。" },
    [94997] = { lv = 38, lvStd = 42, npc = "里夫坦中士", npcid = 258023, side = "A", zone = "河林", pre = { 94983 }, obj = "收集被诅咒的遗物背包，把它交给法霍尔德堡的艾什·安伯霍尔。", text = "河林引导系列（三环）的第二环：里夫坦中士在河林（30.6,49.0）接取；凑齐被诅咒的遗物背包后回法霍尔德堡交给艾什·安伯霍尔（66.6,81.0）。", gains = { xp = 3450, money = 5500 } },
    [95196] = { lv = 48, lvStd = 53, nm = "当心背后！", npc = "萨利·麦克利里", npcid = 260146, side = "A", zone = "Dustwallow Marsh", pre = {95194}, obj = "前往尘泥沼泽与萨利·麦克利里会合，了解关于任务的更多细节。", text = "在塞拉摩旅店接到；出城绕到镇外墓地后头与萨利会合，交付在城门口（63.4,42.4）。", gains = { xp = 1300, rep = { { 72, 75, "Stormwind City" } } } },
    [95198] = { lv = 48, lvStd = 53, nm = "国王归来？", npc = "萨利·麦克利里", npcid = 260271, side = "A", zone = "Dustwallow Marsh", pre = {95196}, obj = "使用军情七处伪装套件，在塞拉摩法师塔内窃听吉安娜及其心腹的密谈。", text = "在塞拉摩城门口接，拿上军情七处伪装套件（269000）进法师塔：伪装成水兵替下守卫，站到位置听完吉安娜的密谈，点掉伪装回城门口交。交完就能同时接《秘密监狱》与《一趟湿活》。", gains = { xp = 1300, rep = { { 72, 100, "Stormwind City" } } } },
    [95263] = { lv = 48, lvStd = 53, nm = "沉重的噩耗", npc = "萨利·麦克利里", npcid = 260271, side = "A", zone = "Dustwallow Marsh", pre = {95262, 96335}, obj = "返回尘泥沼泽，向萨利·麦克利里复命。", text = "由《秘密监狱》或《铁链囚徒》自动转来；回到塞拉摩城门口找萨利·麦克利里（63.4,42.4）交，交完她接着发《事关重大》。", gains = { xp = 2860, rep = { { 72, 75, "Stormwind City" } } } },
    [95264] = { lv = 48, lvStd = 53, nm = "事关重大", npc = "马迪亚斯·肖尔", npcid = 332, side = "A", zone = "Stormwind City", pre = {95263}, obj = "将情报面呈暴风城的马迪亚斯·肖尔。", text = "回暴风城旧城区的军情七处，找马迪亚斯·肖尔（78.3,70.7）交；联盟这条主线到此收尾。", gains = { xp = 1300, money = 8000, rep = { { 72, 100, "Stormwind City" } } } },
    [95309] = { lv = 48, lvStd = 53, nm = "一个兽人都不能少", npc = "乌尔卡中士", npcid = 260383, side = "H", zone = "Prison of Alcaz", pre = {95285}, obj = "进入奥卡兹监狱，找到指挥官福尔卡。", text = "乌尔卡中士在奥卡兹岛近岸的营地（70.3,19.1）发；进本后在里头找到指挥官福尔卡。", gains = { xp = 1300 } },
    [96369] = { lv = 48, lvStd = 53, nm = "给福尔卡的坏消息", side = "H", zone = "Prison of Alcaz", pre = {95454}, obj = "回去向指挥官福尔卡复命。", text = "由《库卡隆的荣耀》接下，回指挥官福尔卡那里交；交完接着就是《大酋长必须知情》。", gains = { xp = 1300 } },
    [96377] = { lv = 48, lvStd = 53, nm = "国家机密", npc = "「剃刀」雷吉克", npcid = 6946, side = "A", zone = "Stormwind City", pre = {96337}, obj = "把文件盒带回暴风城。", text = "带文件盒回暴风城旧城区军情七处找「剃刀」雷吉克（78.3,71.1）交；藏宝海湾的力克希·希基克斯也收同一个盒子，两边报酬相同。", gains = { xp = 6550, rep = { { 76, 150, "Orgrimmar" } } } },
    [96337] = { lv = 48, lvStd = 53, nm = "可贵胜金", npc = "梅森·康纳利", side = "A", zone = "Westfall", pre = {96335}, obj = "按梅森·康纳利给的便条找到他藏的宝物。", text = "本内接到后先出本：去西部荒野月溪镇，旅店二楼点开箱子后面的木板完成，就地交掉拿到文件盒（274041）。", gains = { xp = 11550 } },
    [95483] = { lv = 48, lvStd = 53, nm = "大酋长必须知情", side = "H", zone = "Orgrimmar", pre = {96369}, obj = "把瓦里安·乌瑞恩的下落带回奥格瑞玛，告诉萨尔。", text = "部落线的收尾：由《给福尔卡的坏消息》接下，带消息回奥格瑞玛智慧谷找萨尔（31.7,37.8）交，本外跑腿，不进副本。", gains = { xp = 2405, rep = { { 76, 100, "Orgrimmar" } } } },
    [95285] = { lv = 48, lvStd = 53, nm = "阴差阳错", npc = "乌尔卡中士", npcid = 260383, side = "H", zone = "Dustwallow Marsh", pre = {95284}, obj = "与乌尔卡中士交谈，了解奥卡兹岛上的情况。", text = "库卡隆军士乌尔卡在奥卡兹岛近岸的营地里（70.3,19.1），接取与交付都是他；交完开《有仇必报》与《血红头巾》。", gains = { xp = 1300, money = 2000, rep = { { 76, 75, "Orgrimmar" } } } },
    [95284] = { lv = 48, lvStd = 53, nm = "精锐中的精锐", side = "H", zone = "Dustwallow Marsh", obj = "找到失踪的库卡隆精英。", text = "部落这条线的第一环，在奥卡兹岛近岸的库卡隆营地里接；交完接着是《阴差阳错》。", gains = { xp = 1300, rep = { { 76, 75, "Orgrimmar" } } } },
    [95194] = { lv = 48, lvStd = 53, nm = "塞拉摩的内线", npc = "马迪亚斯·肖尔", npcid = 332, side = "A", zone = "Stormwind City", obj = "找到在塞拉摩的肖尔的特工。", text = "军情七处总部在暴风城旧城区（78.3,70.7），找马迪亚斯·肖尔接；交付在塞拉摩岛的旅店角落，找矮人特工萨利·麦克利里（63.4,42.4），她随后发《当心背后！》。", gains = { xp = 1300, rep = { { 72, 25, "Stormwind City" } } } },
    [95454] = { lv = 48, lvStd = 53, nm = "库卡隆的荣耀", side = "H", pre = {95309}, zone = "Prison of Alcaz", obj = "查明瓦里安·乌瑞恩的下落，并读一读地上的字条。", text = "奥卡兹监狱部落引导链的第一环：进奥卡兹监狱找到瓦里安·乌瑞恩，读地上的字条；后续再把消息带回奥格瑞玛给萨尔。", gains = { xp = 12100, rep = { { 76, 100, "Orgrimmar" } } } },
    [96775] = { lv = 42, lvStd = 46, npc = "马祖康", npcid = 264074, side = "H", zone = "莫高雷", obj = "深入祖尔法拉克，消灭巫医祖穆拉恩，把他的头颅完整地带回来。", text = "接取与上交都是莫高雷的 马祖康（32.5,20.7）：先接任务，再进祖尔法拉克杀巫医祖穆拉恩拿头颅回来交。", gains = { xp = 10100, money = 6500 } },
    [96776] = { lv = 43, lvStd = 51, npc = "奥拉娜·闪蹄", npcid = 268557, side = "H", zone = "莫高雷", obj = "从玛拉顿取回名为安瑟的光辉的水晶，带回给奥拉娜·闪蹄。", text = "奥拉娜·闪蹄在莫高雷（32.6,24.0）接取；安瑟的光辉是玛拉顿内的水晶，拿到后回去交给她。", gains = { xp = 11900, money = 7500 } },
    [97197] = { lv = 46, lvStd = 55, npc = "阿拉娜·风暴行者", npcid = 259119, side = "H", zone = "莫高雷", obj = "从黑石深渊取回火焰之地碎片，带回给阿拉娜·风暴行者。", text = "阿拉娜·风暴行者在莫高雷（33.4,22.4）接取；火焰之地碎片掉自黑石深渊，拿到后回去交给她。", gains = { xp = 14800, money = 8500 } },
    [92914] = { lv = 35, lvStd = 43, nm = "奇怪的水晶塔", npc = "辛德拉水晶塔（43.8,34.3）", zone = "Shen'dralar", si = true, obj = "探索辛德拉，设法寻找与你所见相似的其他水晶塔。", text = "辛德拉线的链头：在野外的水晶塔旁拾取开启（物件起始），就地交给神殿的莫丹特·永影（35.1,46.4）。", gains = { xp = 3600 } },
    [96010] = { lv = 35, lvStd = 41, nm = "水晶塔碎片", npc = "莫丹特·永影（35.1,46.4）", npcid = 253471, zone = "Shen'dralar", pre = { 92914 }, obj = "取回盛格拉斯村和吉尔吉斯村严密看守的水晶塔碎片与残片，交给莫丹特·永影。", text = "碎片被半人马当战利品带回盛格拉斯、吉尔吉斯两个村子，两处都有守卫看着；取齐后回神殿交给莫丹特·永影。", gains = { xp = 2450 } },
    [96018] = { lv = 35, lvStd = 43, nm = "为晶塔供能", npc = "莫丹特·永影（35.1,46.4）", npcid = 253471, zone = "Shen'dralar", pre = { 96010 }, obj = "从辛德拉神殿内取得法力过滤网，用它收集远古魔力水晶，为水晶塔充能后向莫丹特·永影复命。", text = "充能不是打怪掉物品：找不稳定的法力裂隙，裂隙附近会喷出蓝色漂浮小球，要走到球上才会自动吸收拾取；每座塔喂 4 颗，两座塔共 8 颗，都喂满后回莫丹特处复命。", gains = { xp = 3600 } },
    [93016] = { lv = 35, lvStd = 43, nm = "简短的历史课", npc = "莫丹特·永影（35.1,46.4）", npcid = 253471, zone = "Shen'dralar", pre = { 96018 }, obj = "与辛德拉的莫丹特·永影交谈，了解你修复的那些水晶的信息。", text = "纯对话环：回神殿找莫丹特·永影听完辛德拉的来历即可，交完紧接着《会见魔导师》。", gains = { xp = 360 } },
    [93394] = { lv = 35, lvStd = 43, nm = "会见魔导师", npc = "莫丹特·永影（35.1,46.4）", npcid = 253471, zone = "Shen'dralar", pre = { 93016 }, obj = "在辛德拉神殿内找到魔导师基兰迪斯。", text = "进神殿往深处走，找魔导师基兰迪斯（47.4,76.2）对话即可；在神殿里别乱开怪。", gains = { xp = 360 } },
    [93341] = { lv = 35, lvStd = 43, nm = "荒弃花园", npc = "米瑟拉（53.2,75.9）", npcid = 254578, zone = "Shen'dralar", pre = { 93394 }, obj = "调查辛德拉附近的荒弃花园，然后回到附近神殿找米瑟拉复命。", text = "米瑟拉在神殿外（53.2,75.9）；去东南边的荒弃花园查一圈再回来复命，交完就能接《林中传言》。", gains = { xp = 1800 } },
    [93594] = { lv = 35, lvStd = 43, nm = "林中传言", npc = "米瑟拉（53.2,75.9）", npcid = 254578, zone = "Shen'dralar", pre = { 93341 }, obj = "到辛德拉东南角的遗忘花园，找到树灵林地怪。", text = "辛德拉是凄凉之地东南角、与菲拉斯和莫高雷交界处的新区域，客户端里是一张独立地图：神殿外找米瑟拉（53.2,75.9）接，往东南走到遗忘花园找树灵林地怪（69.7,71.8），找到他就地交付；他随即托你进玛拉顿取大地之歌之水（续接《腐朽与懊悔》）。", gains = { xp = 360 } },
    [93404] = { lv = 35, lvStd = 49, nm = "腐朽与懊悔", npc = "林地怪（69.7,71.8）", npcid = 254674, zone = "Shen'dralar", pre = { 93594 }, goals = { { "i", 272186, 1 }, { "i", 272187, 1 } }, obj = "取回大地之歌之水并熄灭林地怪。", text = "接取在辛德拉的遗忘花园，接完与旁边树 NPC 对话开后续；水瓶在玛拉顿：打完公主跳下瀑布、打掉洛特格里普之后，往地精首领方向走的那段水面上有个明显的水球，右键点击即可取到；交付在辛德拉遗忘花园的林地怪处（69.7,71.8），熄灭火焰是回去后点一下完成。", gains = { xp = 11100 } },
    [93606] = { lv = 35, lvStd = 45, nm = "尖叫绝交", npc = "勇敢的科格苏格（72.5,31.5）", npcid = 253527, zone = "Shen'dralar", pre = { 93604 }, obj = "为库尔加带去仁慈的花束和剧毒的阿迦玛甘之血，平息野猪人之间的争端。", text = "《阿迦玛甘之血》交完由科格苏格给；花束的花朵要回辛德拉的荒弃花园里采，血就是上一环从剃刀高地拿回来的那份，两样一起交给他的伴侣智者库尔加，她才肯拿项链来换。交完直接接《遗忘项链》。", gains = { xp = 3900 } },
    [93609] = { lv = 35, lvStd = 45, nm = "遗忘项链", npc = "米瑟拉（53.2,75.9）", npcid = 254578, zone = "Shen'dralar", pre = { 93606 }, obj = "把遗忘项链带给凄凉之地辛德拉神殿的米瑟拉。", text = "由《尖叫绝交》交完直接接到；项链里的魔法已经耗光，带回辛德拉神殿交给米瑟拉，神殿外就能交，这条线到此收尾。", gains = { xp = 4850, money = 13000 } },
    [93601] = { lv = 35, lvStd = 45, nm = "推卸责任", npc = "林地怪（69.7,71.8）", npcid = 254674, zone = "Shen'dralar", pre = { 93404 }, obj = "北上凄凉之地刺背避难所，找一位有分量的野猪人谈谈。", text = "林地怪咬定野猪人偷走了女人的礼物，让你到刺背避难所找野猪人问话：目标就是避难所里的 勇敢的科格苏格（72.5,31.5），交完他正好发《阿迦玛甘之血》。", gains = { xp = 390, money = 600 } },
    [92065] = { lv = 55, lvStd = 60, nm = "光复黑喉", npc = "拉格罗尔", npcid = 6651, zone = "艾萨拉", pre = { 86814 }, goals = { { "i", 249692, 1 } }, obj = "把瓦罗克斯·暗蹄的头颅交给乌索兰的护门者拉格罗尔。", text = "木喉要塞长链收尾：进黑喉要塞杀瓦罗克斯·暗蹄取头颅，回乌索兰交拉格罗尔。", gains = { xp = 13200, rep = { { 576, 150, "木喉要塞" } } } },
    [86814] = { lv = 55, lvStd = 58, nm = "黑喉的反攻", npc = "拉格罗尔", npcid = 6651, zone = "艾萨拉", pre = { 87346 }, obj = "解决黑喉的反攻。", text = "木喉要塞长链第 5 环，交完接《光复黑喉》。", gains = { xp = 7050, rep = { { 576, 150, "木喉要塞" } } } },
    [87346] = { lv = 55, lvStd = 58, nm = "血喉酋长", npc = "拉格罗尔", npcid = 6651, zone = "艾萨拉", pre = { 86798 }, goals = { { "i", 236631, 1 } }, obj = "取回血喉粉碎者。", text = "木喉要塞长链第 4 环。", gains = { xp = 5650, rep = { { 576, 100, "木喉要塞" } } } },
    [86798] = { lv = 55, lvStd = 58, nm = "木喉的增援", npc = "拉格罗尔", npcid = 6651, zone = "木喉要塞", pre = { 86797 }, obj = "到木喉要塞增援。", text = "木喉要塞长链第 3 环。", gains = { xp = 560, rep = { { 576, 50, "木喉要塞" } } } },
    [86797] = { lv = 53, lvStd = 56, nm = "向拉格罗尔复命", npc = "拉格罗尔", npcid = 6651, zone = "艾萨拉", pre = { 86777, 86792, 86796 }, obj = "向护门者拉格罗尔复命。", text = "木喉要塞长链第 2 环：三条前置全做完才能接到。", gains = { xp = 530, rep = { { 576, 25, "木喉要塞" } } } },
    [86777] = { lv = 53, lvStd = 56, nm = "菲达雷德", zone = "艾萨拉", obj = "在艾萨拉完成菲达雷德的任务。", text = "木喉要塞长链的三条并行前置之一。" },
    [86792] = { lv = 55, lvStd = 58, nm = "削减兵力", zone = "艾萨拉", obj = "在艾萨拉削减黑喉兵力。", text = "木喉要塞长链的三条并行前置之一。" },
    [86796] = { lv = 55, lvStd = 58, nm = "萨特，回头见", zone = "艾萨拉", obj = "在艾萨拉处理萨特。", text = "木喉要塞长链的三条并行前置之一。" },
    [9240] = { lv = 40, lvStd = 50, nm = "祖尔法拉克之槌", npc = "守护者奇尔加", zone = "Hinterlands", si = true, opt = true, elite = true, rew = { 9240 }, obj = "到辛特兰祖尔祭坛击杀守护者奇尔加，拾取神圣之槌，再带到辛萨罗顶层祭坛使用，把它变成祖尔法拉克之槌。", text = "可选任务，不打也不影响副本主线。祖尔祭坛在辛特兰（48,67），守护者奇尔加 5 分钟刷一次，祭坛顶上一共 2 个精英，一起清掉；拿到神圣之槌后一路清到辛萨罗最顶端，找到躺着断齿长老的祭坛，背包右键使用神圣之槌，读条完成就变成祖尔法拉克之槌。" },

    [93786] = { lv = 35, lvStd = 36, nm = "血染的警告", npc = "克罗姆罗什", npcid = 256418, side = "H", zone = "河林", obj = "消灭12名草甸溪农场雇农，然后带着你胜利的消息向克罗姆罗什复命。", text = "洛格玛的克罗姆罗什给，和《探囊取物》同批接；目标是草甸溪农场的雇农，农场一带成群刷新，清完回洛格玛交。" },
    [93787] = { lv = 36, lvStd = 36, nm = "探囊取物", npc = "克罗姆罗什", npcid = 256418, side = "H", zone = "河林", obj = "从草甸溪的联盟农场偷取6个饲料袋，然后向克罗姆罗什复命。", text = "与《血染的警告》同批，从草甸溪的联盟农场偷饲料袋；两条都交完，克罗姆罗什才会给《教教他们规矩》。" },
    [94483] = { lv = 36, lvStd = 39, nm = "教教他们规矩", npc = "克罗姆罗什", npcid = 256418, side = "H", zone = "河林", pre = { 93786, 93787 }, obj = "在河流以南消灭8个法霍德牧师和12个法霍德斥候。", text = "前两条交完才开放；目标在河林以南的法霍德一带，牧师和斥候一起清。" },
    [94672] = { lv = 36, lvStd = 41, nm = "暮光逼近", npc = "特兰古尔", npcid = 256710, side = "H", zone = "河林", pre = { 94483 }, obj = "为洛格玛的特兰古尔消灭阳光林地中的8名暮光袭击者和8名暮光新教徒。", text = "洛格玛的特兰古尔给，和《暮光信件》同批；暮光袭击者与新教徒都在阳光林地一带。" },
    [94680] = { lv = 36, lvStd = 41, nm = "暮光信件", npc = "特兰古尔", npcid = 256710, side = "H", zone = "河林", pre = { 94483 }, obj = "为洛格玛的特兰古尔从阳光林地的暮光暗影法师身上夺取3封暮光信件。", text = "与《暮光逼近》同批，信件由暮光暗影法师掉落，凑 3 封；两条交完特兰古尔才给《挖掘答案》。" },
    [94727] = { lv = 36, lvStd = 40, nm = "挖掘答案", npc = "特兰古尔", npcid = 256710, side = "H", zone = "河林", pre = { 94672, 94680 }, obj = "说服阳光林地的一名暮光之锤矿工，让他泄露秘密。", text = "两条都交完特兰古尔才给；去阳光林地说服暮光之锤矿工套出消息，回程把结果交给阳光林地的棍趾。" },
    [95417] = { lv = 36, lvStd = 40, nm = "紫色的家伙", npc = "棍趾", npcid = 260931, side = "H", zone = "河林", pre = { 94727 }, obj = "为棍趾在阳光林地下方的洞穴中寻找失踪的食人魔。", text = "棍趾给，去阳光林地下方的洞穴里找失踪的食人魔；这半段交在洞穴里的蛮兵手上。" },
    [95601] = { lv = 36, lvStd = 40, nm = "紫色的家伙", npc = "暮光蛮兵", npcid = 261208, side = "H", zone = "河林", pre = { 95417 }, obj = "消灭5名强化蛮兵和10名暮光仪式师，然后回到阳光林地的棍趾那里。", text = "接上一半，在洞穴里清强化蛮兵与暮光仪式师，回阳光林地交棍趾。" },
    [95602] = { lv = 36, lvStd = 40, nm = "令人作呕的光", npc = "棍趾", npcid = 260931, side = "H", zone = "河林", pre = { 94727 }, obj = "摧毁在阳光林地下方洞穴中发现的5个暮光仪式法阵。", text = "与《紫色的家伙》并行的另一条，摧毁洞穴里的暮光仪式法阵，共 5 处。" },
    [95427] = { lv = 36, lvStd = 41, nm = "再也没有暮光！", npc = "棍趾", npcid = 260931, side = "H", zone = "河林", pre = { 95601, 95602 }, obj = "在阳光林地的洞穴中消灭乔格扎克，并为棍趾收集他们的头颅。", text = "两个分支都交完才给；在洞穴里打乔格扎克并收集头颅，回棍趾复命。" },
    [95418] = { lv = 36, lvStd = 40, nm = "传播消息", npc = "棍趾", npcid = 260931, side = "H", zone = "河林", pre = { 95427 }, obj = "将乔格的徽记交给洛格玛的特兰古尔。", text = "把乔格的徽记带回洛格玛交给特兰古尔，这条是往北边食人魔城市去的引子。" },
    [95420] = { lv = 36, lvStd = 40, nm = "巨人之国", npc = "特兰古尔", npcid = 256710, side = "H", zone = "河林", pre = { 95418 }, obj = "将乔格的徽记交给北方的食人魔城市。", text = "特兰古尔让你把徽记送到北边的食人魔城市博尔德罗克，交给克鲁格菲斯特。" },
    [95424] = { lv = 36, lvStd = 41, nm = "强权即公理", npc = "克鲁格菲斯特", npcid = 255829, side = "H", zone = "河林", pre = { 95420 }, obj = "为博尔德罗克的克鲁格菲斯特消灭7名暮光虐待者和7名暮光唤火者。", text = "博尔德罗克的克鲁格菲斯特给，清洞穴里的暮光虐待者与唤火者；和《不配的冠军》同批。" },
    [95425] = { lv = 36, lvStd = 42, nm = "不配的冠军", npc = "克鲁格菲斯特", npcid = 255829, side = "H", zone = "河林", pre = { 95420 }, obj = "从克朗克那里为博尔德罗克的克鲁格菲斯特收回颅骨重锤。", text = "与《强权即公理》同批，从克朗克手里夺回颅骨重锤。" },
    [94745] = { lv = 38, lvStd = 44, nm = "杀出一条血路", npc = "达格罗什", npcid = 258570, side = "H", zone = "河林", pre = { 94744 }, obj = "为达格罗什击败暮光之帷内的8名暮光狂热者、8名暮光腐蚀者和8名暮光勇士。", text = "达格罗什在罗格玛以西的山地；这是暮光之帷清怪线的一支，狂热者、腐蚀者、勇士各 8 个。" },
    [94748] = { lv = 38, lvStd = 44, nm = "斩断锁链", npc = "达格罗什", npcid = 258570, side = "H", zone = "河林", pre = { 94744 }, obj = "为达格罗什解救暮光之帷内的5名洛格玛斥候。", text = "与《杀出一条血路》同批，在暮光之帷救出 5 名洛格玛斥候；两条都交完才给《提头来见》。" },
    [94768] = { lv = 38, lvStd = 46, nm = "提头来见", npc = "达格罗什", npcid = 258570, side = "H", zone = "河林", pre = { 94745, 94748 }, obj = "在暮光之帷击败霸主基尔加，把他的徽记带给达格罗什。", text = "前两条交完才开放；在暮光之帷打败霸主基尔加，把徽记带回给达格罗什。" },
    [95278] = { lv = 38, lvStd = 45, nm = "是时候了，兄弟……", npc = "达格罗什", npcid = 258570, side = "H", zone = "河林", pre = { 94768 }, obj = "将信件交给洛格玛的克罗姆罗什。", text = "达格罗什托你带信回洛格玛交给克罗姆罗什；交完才开放《莫格之眼》与《暮光宝典》。" },
